 pred=read(RUN/'test_predictions.json')['n1000_seed101'];zz=np.array(out['action_success_labels']);fixed_choice=np.array(pred['choices']['best_fixed']);diff=zz[np.arange(len(zz)),fixed_choice]-zz[:,0];rng=np.random.default_rng(312);samples=[float(diff[rng.integers(len(diff),size=len(diff))].mean()) for _ in range(2000)];fixed_pair=dict(difference=float(diff.mean()),ci95=np.quantile(samples,[.025,.975]).tolist(),resamples=2000);dump(RUN/'fixed_policy_vs_keep.json',fixed_pair)
